/// use std::ffi::CString;
///
/// let mut options = CheckoutOptions::new();
/// {
///     let label = CString::new("mine").unwrap();
///     options.as_mut().set_our_label(Some(&label));
/// }
/// let _ = options.as_ref().our_label();
