			linelen = prefixlen;
		}

		git_str_putc(&usage, ' ');
		linelen += git_str_len(&opt) + 1;

		git_str_puts(&usage, git_str_cstr(&opt));

		if (git_str_oom(&usage)) {
			error = -1;
			goto done;
		}
	}

	error = fprintf(file, "%s\n", git_str_cstr(&usage));

