        #[doc(alias = "cli_opt_spec.type")]
        pub fn set_target(&mut self, target: Target<'p>) {
            fn erase<T>(variable: Option<&T>) -> *mut c_void {
                variable.map_or(ptr::null_mut(), |v| ptr::from_ref(v).cast_mut().cast())
            }
