            | (Target::Switch(a), Target::Switch(b))
            | (Target::Accumulator(a), Target::Accumulator(b)) => {
                assert_eq!(a.map(core::ptr::from_ref), b.map(core::ptr::from_ref));
            }
            (Target::Value(a), Target::Value(b)) | (Target::Arg(a), Target::Arg(b)) => {
                assert_eq!(a.map(core::ptr::from_ref), b.map(core::ptr::from_ref));
            }
